 document.addEventListener('DOMContentLoaded', () => {
     const form = document.getElementById('contact-form');
     const statusMessage = document.getElementById('status-message');

     form.addEventListener('submit', (event) => {
         event.preventDefault();

         // Reset status message
         statusMessage.textContent = '';
         statusMessage.className = '';

         // Validation
         const inputs = form.querySelectorAll('input[required]');
         let firstInvalid = null;
         let errors = [];

         inputs.forEach(input => {
             // Remove existing error indication
             input.setAttribute('aria-invalid', 'false');

             if (!input.value.trim()) {
                 input.setAttribute('aria-invalid', 'true');
                 errors.push(`${input.previousElementSibling.textContent.replace('*', '').trim()} is required.`);
                 if (!firstInvalid) {
                     firstInvalid = input;
                 }
             } else if (input.type === 'email' && !isValidEmail(input.value)) {
                 input.setAttribute('aria-invalid', 'true');
                 errors.push('Please enter a valid email address.');
                 if (!firstInvalid) {
                     firstInvalid = input;
                 }
             }
         });

         if (firstInvalid) {
             statusMessage.textContent = 'Please correct the errors before submitting.';
             statusMessage.className = 'error';
             firstInvalid.focus();
             return;
         }

         // Mock submission
         statusMessage.textContent = 'Thank you! Your message has been sent successfully.';
         statusMessage.className = 'success';
         form.reset();

         // Reset aria-invalid on fields after reset
         inputs.forEach(input => input.setAttribute('aria-invalid', 'false'));
     });

     function isValidEmail(email) {
         return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
     }
 });

