form.addEventListener('submit', (event) => {
    event.preventDefault();

    // Reset status message
    statusMessage.textContent = '';
    statusMessage.className = '';

    // Reset individual errors
    const errorTexts = form.querySelectorAll('.error-text');
    errorTexts.forEach(el => {
        el.textContent = '';
        el.hidden = true;
    });

    const inputs = form.querySelectorAll('input');
    let firstInvalid = null;

    inputs.forEach(input => {
        input.setAttribute('aria-invalid', 'false');
        const errorId = input.getAttribute('aria-describedby')?.split(' ').find(id => id.endsWith('-error'));
        const errorEl = errorId ? document.getElementById(errorId) : null;

        let errorMessage = '';

        if (input.hasAttribute('required') && !input.value.trim()) {
            errorMessage = `Error: ${getLabelText(input)} is required.`;
        } else if (input.type === 'email' && input.value.trim() && !isValidEmail(input.value)) {
            errorMessage = 'Error: Please enter a valid email address.';
        }

        if (errorMessage) {
            input.setAttribute('aria-invalid', 'true');
            if (errorEl) {
                errorEl.textContent = errorMessage;
                errorEl.hidden = false;
            }
            if (!firstInvalid) {
                firstInvalid = input;
            }
        }
    });

    if (firstInvalid) {
        statusMessage.textContent = 'Please correct the errors before submitting.';
        statusMessage.className = 'error';
        firstInvalid.focus();
        return;
    }

    // Mock submission
    statusMessage.textContent = 'Thank you! Your message has been sent successfully.';
    statusMessage.className = 'success';
    form.reset();

    // Reset aria-invalid on fields after reset
    inputs.forEach(input => input.setAttribute('aria-invalid', 'false'));
});

function getLabelText(input) {
    const label = document.querySelector(`label[for="${input.id}"]`);
    return label ? label.textContent.replace('*', '').trim() : 'This field';
}

