    <style>
        :root {
            --primary-color: #005a9c;
            --primary-hover: #004477;
            --text-color: #333;
            --label-color: #555;
            --border-color: #ccc;
            --focus-ring: #005a9c;
            --bg-color: #f9f9f9;
            --container-bg: #ffffff;
            --error-color: #d32f2f;
            --helper-text-color: #666;
        }

