            box-sizing: border-box;
        }

        .skip-link {
            position: absolute;
            top: -40px;
            left: 0;
            background: var(--primary-color);
            color: white;
            padding: 8px;
            z-index: 100;
            transition: top 0.2s;
            text-decoration: none;
        }

        .skip-link:focus {
            top: 0;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol";
            line-height: 1.6;
            color: var(--text-color);
            background-color: var(--bg-color);
            margin: 0;
            padding: 0;
        }

        header {
            background-color: #fff;
            padding: 2rem 1rem;
            text-align: center;
            border-bottom: 1px solid var(--border-color);
        }

        h1 {
            margin: 0;
            font-weight: 600;
        }

        main {
            padding: 2rem 1rem;
        }

        main:focus {
            outline: none;
        }

        .container {
            max-width: 600px;
            margin: 0 auto;
            background: var(--container-bg);
            padding: 2rem;
            border-radius: 8px;
            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
        }

        .required-legend {
            font-size: 0.875rem;
            color: var(--label-color);
            margin-bottom: 1.5rem;
        }

        .required-mark {
            color: var(--error-color);
        }

        .form-field {
            margin-bottom: 1.5rem;
        }

        .form-field label {
            display: block;
            font-weight: 500;
            margin-bottom: 0.5rem;
            color: var(--label-color);
        }

        .form-field input {
            width: 100%;
            padding: 0.75rem;
            border: 1px solid var(--border-color);
            border-radius: 4px;
            font-size: 1rem;
            font-family: inherit;
            transition: border-color 0.2s, box-shadow 0.2s;
        }

        .form-field input:focus {
            outline: none;
            border-color: var(--focus-ring);
            box-shadow: 0 0 0 3px rgba(0, 90, 156, 0.25);
        }

        .helper-text {
            font-size: 0.875rem;
            color: var(--helper-text-color);
            margin-top: 0.25rem;
        }

        .error-text {
            font-size: 0.875rem;
            color: var(--error-color);
            margin-top: 0.25rem;
            font-weight: 500;
        }

        .form-actions {
            margin-top: 2rem;
        }

        button {
            background-color: var(--primary-color);
            color: white;
            padding: 0.75rem 1.5rem;
            border: none;
            border-radius: 4px;
            font-size: 1rem;
            font-weight: 600;
            cursor: pointer;
            transition: background-color 0.2s;
            width: 100%;
        }

        button:hover {
            background-color: var(--primary-hover);
        }

        button:focus {
            outline: none;
            box-shadow: 0 0 0 3px rgba(0, 90, 156, 0.5);
