        }

        @media (max-width: 480px) {
            .container {
                padding: 1.5rem;
            }
        }

        /* High Contrast / Forced Colors Mode */
        @media (forced-colors: active) {
            .form-field input:focus,
            button:focus {
                outline: 2px solid ButtonText;
            }
        }
    </style>
</head>
<body>
    <a href="#main-content" class="skip-link">Skip to main content</a>
    <header>
        <h1>Contact Support</h1>
    </header>
    <main id="main-content" tabindex="-1">
        <div class="container">
            <p>Please fill out the form below and our support team will get back to you as soon as possible.</p>
            <p class="required-legend" aria-hidden="true"><span class="required-mark">*</span> indicates a required field</p>

            <form id="contact-form" novalidate>
                <div class="form-field">
                    <label for="full-name">Full Name <span class="required-mark" aria-hidden="true">*</span></label>
                    <input type="text" id="full-name" name="full-name" required autocomplete="name" aria-describedby="name-error">
                    <p id="name-error" class="error-text" hidden></p>
                </div>

                <div class="form-field">
                    <label for="email">Email Address <span class="required-mark" aria-hidden="true">*</span></label>
                    <input type="email" id="email" name="email" required autocomplete="email" aria-describedby="email-error">
                    <p id="email-error" class="error-text" hidden></p>
                </div>

                <div class="form-field">
                    <label for="phone">Phone Number (optional)</label>
                    <input type="tel" id="phone" name="phone" autocomplete="tel" aria-describedby="phone-help phone-error">
                    <p id="phone-help" class="helper-text">Expected format: +1 (555) 000-0000</p>
                    <p id="phone-error" class="error-text" hidden></p>
                </div>

                <div id="status-message" role="status" aria-live="polite"></div>

                <div class="form-actions">
                    <button type="submit">Send Message</button>
                </div>
            </form>
        </div>
    </main>
    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const form = document.getElementById('contact-form');
            const statusMessage = document.getElementById('status-message');

            form.addEventListener('submit', (event) => {
                event.preventDefault();

                // Reset status message
                statusMessage.textContent = '';
                statusMessage.className = '';

                // Reset individual errors
                const errorTexts = form.querySelectorAll('.error-text');
                errorTexts.forEach(el => {
                    el.textContent = '';
                    el.hidden = true;
                });

                const inputs = form.querySelectorAll('input');
                let firstInvalid = null;

                inputs.forEach(input => {
                    input.setAttribute('aria-invalid', 'false');
                    const errorId = input.getAttribute('aria-describedby')?.split(' ').find(id => id.endsWith('-error'));
                    const errorEl = errorId ? document.getElementById(errorId) : null;

                    let errorMessage = '';

                    if (input.hasAttribute('required') && !input.value.trim()) {
                        errorMessage = `Error: ${getLabelText(input)} is required.`;
                    } else if (input.type === 'email' && input.value.trim() && !isValidEmail(input.value)) {
                        errorMessage = 'Error: Please enter a valid email address.';
                    }

                    if (errorMessage) {
                        input.setAttribute('aria-invalid', 'true');
                        if (errorEl) {
                            errorEl.textContent = errorMessage;
                            errorEl.hidden = false;
                        }
                        if (!firstInvalid) {
                            firstInvalid = input;
                        }
                    }
                });

                if (firstInvalid) {
                    statusMessage.textContent = 'Please correct the errors before submitting.';
                    statusMessage.className = 'error';
                    firstInvalid.focus();
                    return;
                }

                // Mock submission
                statusMessage.textContent = 'Thank you! Your message has been sent successfully.';
                statusMessage.className = 'success';
                form.reset();

                // Reset aria-invalid on fields after reset
                inputs.forEach(input => input.setAttribute('aria-invalid', 'false'));
            });

            function getLabelText(input) {
                const label = document.querySelector(`label[for="${input.id}"]`);
                return label ? label.textContent.replace('*', '').trim() : 'This field';
            }

            function isValidEmail(email) {
                return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
            }
        });
    </script>
</body>
</html>
