                    <input type="text" id="full-name" name="full-name" required autocomplete="name" aria-describedby="name-error">
                    <p id="name-error" class="error-text" hidden></p>
                </div>

                <div class="form-field">
                    <label for="email">Email Address <span class="required-mark" aria-hidden="true">*</span></label>
                    <input type="email" id="email" name="email" required autocomplete="email" aria-describedby="email-error">
                    <p id="email-error" class="error-text" hidden></p>
                </div>

                <div class="form-field">
                    <label for="phone">Phone Number (optional)</label>
                    <input type="tel" id="phone" name="phone" autocomplete="tel" aria-describedby="phone-help phone-error">
                    <p id="phone-help" class="helper-text">Expected format: +1 (555) 000-0000</p>
                    <p id="phone-error" class="error-text" hidden></p>
                </div>

                <div id="status-message" role="status" aria-live="polite"></div>

